use std::os::windows::process::CommandExt;
use std::{sync::{Mutex,Condvar,OnceLock},io::{BufRead,BufReader},path::PathBuf,process::{Command,Stdio},time::Duration};
use tauri::Manager;
use windows_sys::Win32::UI::{WindowsAndMessaging::*,Input::KeyboardAndMouse::*};
static EVENTS:OnceLock<(Mutex<Vec<String>>,Condvar)>=OnceLock::new();
pub fn observe(stage:&str){if !std::env::args().any(|a|a=="--quick-native-audit"){return;}let(q,cv)=EVENTS.get_or_init(Default::default);q.lock().unwrap().push(stage.into());cv.notify_all();}
fn cursor()->usize{EVENTS.get_or_init(Default::default).0.lock().unwrap().len()}
fn wait(after:usize,needle:&str)->Result<(),String>{let(q,cv)=EVENTS.get_or_init(Default::default);let(q,result)=cv.wait_timeout_while(q.lock().unwrap(),Duration::from_secs(20),|q|!q.iter().skip(after).any(|s|s.contains(needle))).unwrap();if result.timed_out(){return Err(format!("Timed out waiting for {needle}; events={q:?}"));}Ok(())}
unsafe fn keys(expected:usize,events:&[(u16,u32)])->Result<(),String>{if GetForegroundWindow()as usize!=expected{return Err("Audit focus changed: no input sent".into());}let input:Vec<_>=events.iter().map(|(vk,flags)|INPUT{r#type:INPUT_KEYBOARD,Anonymous:INPUT_0{ki:KEYBDINPUT{wVk:0,wScan:MapVirtualKeyW(*vk as u32,MAPVK_VK_TO_VSC)as u16,dwFlags:*flags|KEYEVENTF_SCANCODE|if [VK_LEFT,VK_RIGHT,VK_UP,VK_DOWN,VK_HOME,VK_END].contains(vk){KEYEVENTF_EXTENDEDKEY}else{0},time:0,dwExtraInfo:0}}}).collect();if SendInput(input.len()as u32,input.as_ptr(),std::mem::size_of::<INPUT>()as i32)!=input.len()as u32{return Err("Audit SendInput failed".into());}Ok(())}
pub fn start(app:&tauri::AppHandle)->Result<(),String>{let args:Vec<_>=std::env::args().collect();let Some(index)=args.iter().position(|a|a=="--quick-native-audit")else{return Ok(())};let dir=PathBuf::from(args.get(index+1).ok_or("Audit directory missing")?);if !args.iter().any(|a|a=="--integration-test")||!app.path().app_config_dir().map_err(|e|e.to_string())?.starts_with(&dir){return Err("Audit requires isolated integration profile".into());}let app=app.clone();std::thread::spawn(move||{let result=run(&app,&dir);let _=std::fs::write(dir.join("result.json"),serde_json::json!({"success":result.is_ok(),"error":result.err()}).to_string());app.state::<crate::State>().quit_approved.store(true,std::sync::atomic::Ordering::SeqCst);app.exit(0);});Ok(())}
fn run(app:&tauri::AppHandle,dir:&std::path::Path)->Result<(),String>{
 let clear_mode=std::env::args().any(|a|a=="--quick-native-clear");
 wait(0,"main-ready")?;wait(0,"mounted")?;wait(0,"quick-loaded")?;
 let script=dir.join("receiver.ps1");let result_file=dir.join("received.txt");
 let mut command=Command::new(std::path::PathBuf::from(std::env::var_os("SystemRoot").unwrap()).join("System32/WindowsPowerShell/v1.0/powershell.exe"));command.creation_flags(0x08000000);let mut child=command.args(["-NoProfile","-STA","-File"]).arg(script).arg("-Result").arg(&result_file).stdout(Stdio::piped()).spawn().map_err(|e|e.to_string())?;
 let mut injected_alt=false;
 let result=(||->Result<(),String>{let mut output=BufReader::new(child.stdout.take().ok_or("Receiver output missing")?);let mut line=String::new();output.read_line(&mut line).map_err(|e|e.to_string())?;let target:usize=line.trim().strip_prefix("HWND ").ok_or(format!("Receiver not ready: {line}"))?.parse().map_err(|_|"Invalid receiver HWND")?;crate::platform::focus_target(target)?;
 let before=cursor();unsafe{if [VK_MENU,VK_CONTROL,VK_SHIFT].iter().any(|key|GetAsyncKeyState(*key as i32)<0){return Err("Audit waits for no physical modifiers".into());}keys(target,&[(VK_MENU,0)])?;injected_alt=true;}
 wait(before,"audit-alt-down")?;let held=unsafe{GetAsyncKeyState(VK_MENU as i32)<0};if !held{unsafe{keys(target,&[(VK_MENU,KEYEVENTF_KEYUP)])?;}}let main=app.get_webview_window("main").ok_or("Main missing")?;let saved_before=crate::materials::materials_packs(main.clone(),app.state())?["packs"].clone();let before_release=cursor();crate::quick_materials::request_toggle(app,true)?;
 wait(before,"quick-loaded")?;let quick=app.get_webview_window("materials-quick").ok_or("Quick missing")?;
 if held{if !quick.is_visible().unwrap_or(false)||result_file.exists(){return Err("L release must leave quick open without pasting".into());}unsafe{keys(target,&[(0x4c,KEYEVENTF_KEYUP)])?;}if result_file.exists(){return Err("L release pasted unexpectedly".into());}unsafe{if clear_mode{keys(target,&[(VK_RIGHT,0),(VK_RIGHT,KEYEVENTF_KEYUP),(VK_MENU,KEYEVENTF_KEYUP)])?;}else{keys(target,&[(VK_RIGHT,0),(VK_RIGHT,KEYEVENTF_KEYUP),(VK_LEFT,0),(VK_LEFT,KEYEVENTF_KEYUP),(VK_MENU,KEYEVENTF_KEYUP)])?;}}}
 if clear_mode{if !held{return Err("Clear audit requires held modifier sequence".into());}wait(before_release,"clear-confirm-ready")?;let before=crate::materials::materials_packs(main.clone(),app.state())?;if before["workspace"]["items"].as_array().map(|a|a.len())!=Some(3)||result_file.exists(){return Err("Clear executed before confirmation".into());}unsafe{keys(target,&[(VK_RETURN,0),(VK_RETURN,KEYEVENTF_KEYUP)])?;}wait(before_release,"quick-clear-done")?;let after=crate::materials::materials_packs(main,app.state())?;if !after["workspace"]["items"].as_array().is_some_and(|a|a.is_empty())||after["undo"]["items"].as_array().map(|a|a.len())!=Some(3)||after["packs"]!=saved_before||quick.is_visible().unwrap_or(true){return Err("Clear/undo/library invariant failed".into());}unsafe{keys(target,&[(VK_RIGHT,0),(VK_RIGHT,KEYEVENTF_KEYUP)])?;}line.clear();output.read_line(&mut line).map_err(|e|e.to_string())?;if line.trim()!="AFTER"{return Err("Keyboard not restored after clear".into());}std::fs::write(dir.join("verified.json"),serde_json::json!({"clearConfirmed":true,"beforeConfirmPreserved":true,"undoCount":3,"savedPacksUnchanged":true,"quickClosed":true,"keyboardRestored":true}).to_string()).map_err(|e|e.to_string())?;return Ok(());}
 line.clear();output.read_line(&mut line).map_err(|e|e.to_string())?;if line.trim()!="PASTE"{return Err(format!("Receiver did not receive Ctrl+V: {line}"));}
 wait(before_release,"paste-result Ok")?;if quick.is_visible().unwrap_or(true){return Err("Quick did not close after paste".into());}
 unsafe{keys(target,&[(VK_RIGHT,0),(VK_RIGHT,KEYEVENTF_KEYUP)])?;}line.clear();output.read_line(&mut line).map_err(|e|e.to_string())?;if line.trim()!="AFTER"{return Err("Keyboard was not restored to the receiving input".into());}
 let files=std::fs::read_to_string(&result_file).map_err(|e|e.to_string())?;let paths:Vec<_>=files.lines().map(PathBuf::from).collect();if paths.len()!=3{return Err(format!("Expected prompt + image + file, got {}",paths.len()));}let prompt=std::fs::read_to_string(&paths[0]).map_err(|e|e.to_string())?;if !prompt.contains("NATIVE_AUDIT_TEXT"){return Err("Prompt text missing".into());}if std::fs::read(&paths[1]).map_err(|e|e.to_string())?!=std::fs::read(dir.join("image.png")).map_err(|e|e.to_string())?{return Err("Image differs".into());}if std::fs::read(&paths[2]).map_err(|e|e.to_string())?!=b"NATIVE_AUDIT_FILE"{return Err("File differs".into());}std::fs::write(dir.join("verified.json"),serde_json::json!({"releaseMode":if held{"held"}else{"releasedBeforeOpen"},"lReleaseNoPaste":if held{Some(true)}else{None},"releasePasted":true,"quickClosed":true,"keyboardRestored":true,"files":3,"textVerified":true,"imageBytesVerified":true,"fileBytesVerified":true}).to_string()).map_err(|e|e.to_string())?;Ok(())})();
 if injected_alt{unsafe{let input=INPUT{r#type:INPUT_KEYBOARD,Anonymous:INPUT_0{ki:KEYBDINPUT{wVk:VK_MENU,wScan:0,dwFlags:KEYEVENTF_KEYUP,time:0,dwExtraInfo:0}}};SendInput(1,&input,std::mem::size_of::<INPUT>()as i32);}}
 // Only the audit's own receiver is closed; its FormClosed handler restores the clipboard.
 unsafe{let title:Vec<u16>="before-you-do native paste verification".encode_utf16().chain(Some(0)).collect();let hwnd=FindWindowW(std::ptr::null(),title.as_ptr());if !hwnd.is_null(){PostMessageW(hwnd,WM_CLOSE,0,0);}}
 let _=child.wait();result
}
